/// `data/minecraft/worldgen/structure/<id>.json` decoded by itself (the full structure registry needs structure types that
/// are not ported yet).
fn structure(id: &str) -> Holder<dyn Structure> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data");
    let json: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join(format!("minecraft/worldgen/structure/{id}.json")))
            .expect("structure json"),
    )
    .unwrap();
    let source: Arc<dyn WorldgenDataSource> = Arc::new(FsDataSource::new(root));
    let cells = Cells::new(source);
    let ctx = DecodeCtx {
        worldgen: &WORLD.worldgen,
        biomes: &WORLD.biomes,
        cells: &cells,
    };
    Holder::direct(decode_direct(&json, &ctx).unwrap_or_else(|e| panic!("{id}.json: {e:?}")))
}

/// The nether `GenEnv` of `seed` (real nether generator + random state; the terrain of the placement regions stays synthetic).
fn nether_env(seed: i64) -> Arc<GenEnv> {
    let w = &*WORLD;
    let settings = w
        .worldgen
        .noise_settings(&Identifier::with_default_namespace("nether").unwrap())
        .expect("nether noise settings");
    let source = biome_source_from_json(
        &serde_json::json!({"type": "minecraft:multi_noise", "preset": "minecraft:nether"}),
        &w.worldgen,
        &w.biomes,
    )
    .expect("nether biome source");
    let generator = Arc::new(
        NoiseBasedChunkGenerator::new(
            source,
            Arc::new(settings),
            w.worldgen.clone(),
            w.biomes.clone(),
        )
        .expect("nether generator"),
    );
    let base = gen_env(seed);
    Arc::new(GenEnv {
        dimension: Identifier::with_default_namespace("the_nether").unwrap(),
        seed,
        random_state: Arc::new(RandomState::create(
            w.worldgen.clone(),
            seed,
            generator.settings(),
        )),
        generator,
        biomes: base.biomes.clone(),
        registries: base.registries.clone(),
        structures: base.structures.clone(),
        start_cache: Default::default(),
        structure_state: None,
        structure_check: mc_game::world::level::levelgen::structure::check::StructureCheck::new(
            Box::new(mc_game::world::level::levelgen::structure::check::NoChunkScan),
        ),
        structure_template_manager: base.structure_template_manager.clone(),
        generate_structures: true,
        level_height: level_height(),
    })
}

/// Mirror of `ScatteredStructuresOracle.fold`: the `B` lines of each chunk as one `B* cx cz count fnv` line.
fn fold(lines: Vec<String>) -> Vec<String> {
    let mut out = Vec::new();
    let mut group: Option<(i32, i32, u64, Fnv)> = None;
    let flush = |group: &mut Option<(i32, i32, u64, Fnv)>, out: &mut Vec<String>| {
        if let Some((cx, cz, count, fnv)) = group.take() {
            out.push(format!("B* {cx} {cz} {count} {}", fnv.hex()));
        }
    };
    for line in lines {
        if line.starts_with("B ") {
            let t: Vec<&str> = line.split(' ').collect();
            let (x, z) = (
                t[1].parse::<i32>().unwrap().div_euclid(16),
                t[3].parse::<i32>().unwrap().div_euclid(16),
            );
            if group.as_ref().is_some_and(|g| (g.0, g.1) != (x, z)) {
                flush(&mut group, &mut out);
            }
            let g = group.get_or_insert_with(|| (x, z, 0, Fnv::default()));
            g.3.s(&line);
            g.2 += 1;
        } else {
            flush(&mut group, &mut out);
            out.push(line);
        }
    }
    flush(&mut group, &mut out);
    out
}

/// Keys of a mob tag that `finalizeSpawn`, the unseeded `Entity.random` and the UUID decide (mirror of the oracle's `VOLATILE`).
const VOLATILE: [&str; 12] = [
    "UUID",
    "attributes",
    "LeftHanded",
    "CanPickUpLoot",
    "CanBreakDoors",
    "IsBaby",
    "equipment",
    "drop_chances",
    "variant",
    "sound_variant",
    "Age",
    "ForcedAge",
];

/// Mirror of `ScatteredStructuresOracle.TEMPLATE_ENTITY_KEYS`.
const TEMPLATE_ENTITY_KEYS: [&str; 3] = ["id", "Pos", "Rotation"];

/// Mirror of `ScatteredStructuresOracle.normalizeEntity`.
fn normalize_entity(line: &str, template_entities_only_basics: bool) -> String {
    let mut t = line.splitn(4, ' ');
    let (n, cx, cz, snbt) = (
        t.next().unwrap(),
        t.next().unwrap(),
        t.next().unwrap(),
        t.next().unwrap(),
    );
    let mut tag =
        mc_nbt::snbt::parse_compound(snbt).unwrap_or_else(|e| panic!("entity snbt {snbt}: {e:?}"));
    if template_entities_only_basics {
        let others: Vec<String> = tag
            .keys()
            .filter(|k| !TEMPLATE_ENTITY_KEYS.contains(&k.as_str()))
            .cloned()
            .collect();
        for key in others {
            tag.remove(&key);
        }
    }
    for key in VOLATILE {
        tag.remove(key);
    }
    format!("{n} {cx} {cz} {}", Tag::Compound(tag))
}

fn generate(
    structure: &Holder<dyn Structure>,
    env: &Arc<GenEnv>,
    seed: i64,
    cx: i32,
    cz: i32,
) -> Option<StructureStart> {
    let valid = |_: BiomeId| true;
    let height: LevelHeight = level_height();
    let mut context = GenerationContext::new(env, seed, ChunkPos::new(cx, cz), height, &valid);
    let stub = structure
        .value()
        .find_valid_generation_point(&mut context)?;
    let builder = stub.get_pieces_builder(&mut context);
    let start = StructureStart::new(structure.clone(), ChunkPos::new(cx, cz), 0, builder.build());
    (!start.piece_container.pieces.is_empty()).then_some(start)
}

/// Debugging: `SCATTERED_FULL=<dir>` replays `<dir>/<id>.txt` generated with the oracle's `full` flag (block lines unfolded).
fn full_mode() -> Option<String> {
    std::env::var("SCATTERED_FULL").ok()
}

fn read_fixture(id: &str) -> String {
    if let Some(dir) = full_mode() {
        return std::fs::read_to_string(format!("{dir}/{id}.txt")).expect("full fixture");
    }
    let path = format!(
        "{}/tests/fixtures/scattered/{id}.txt.gz",
        env!("CARGO_MANIFEST_DIR")
    );
    let mut text = String::new();
    GzDecoder::new(std::fs::File::open(&path).unwrap_or_else(|e| panic!("{path}: {e}")))
        .read_to_string(&mut text)
        .unwrap();
    text
}

/// What a fixture covered, for the per-structure coverage assertions.
#[derive(Default)]
struct Coverage {
    starts: usize,
    valid: usize,
    pieces: usize,
    placements: usize,
    dump_lines: usize,
    /// `Template:"..."` values of the piece tags.
    templates: BTreeSet<String>,
    /// Count of dump lines containing the given needle (see `needles`).
    needles: Vec<usize>,
    /// `placement|mossiness|overgrown|vines|replace_with_blackstone` of the ruined portal pieces.
    portal_setups: BTreeSet<String>,
}

/// The value of `key` (up to the next `,` or `}`) in a piece tag.
fn tag_field<'a>(piece: &'a str, key: &str) -> &'a str {
    let rest = &piece[piece
        .find(key)
        .unwrap_or_else(|| panic!("{key} in {piece}"))
        + key.len()..];
    rest[..rest.find([',', '}']).unwrap()].trim_matches('"')
}

/// Replays the fixture of `id`; every difference is collected, none is tolerated.
fn check(id: &str, nether: bool, needles: &[&str]) -> Coverage {
    let fixture = read_fixture(id);
    let structure = structure(id);
    let mut lines = fixture.lines().peekable();
    let mut cov = Coverage {
        needles: vec![0; needles.len()],
        ..Default::default()
    };
    let mut failures: Vec<String> = Vec::new();
    while let Some(header) = lines.next() {
        let h: Vec<&str> = header.split(' ').collect();
        assert_eq!(h[0], "START", "{header}");
        assert_eq!(h[1], id);
        let (seed, cx, cz, count) = (
            h[2].parse::<i64>().unwrap(),
            h[3].parse::<i32>().unwrap(),
            h[4].parse::<i32>().unwrap(),
            h[5].parse::<i32>().unwrap(),
        );
        cov.starts += 1;
        let env = if nether {
            nether_env(seed)
        } else {
            gen_env(seed)
        };
        let start = generate(&structure, &env, seed, cx, cz);
        if count < 0 {
            if start.is_some() {
                failures.push(format!(
                    "start {seed} {cx} {cz}: vanilla has no valid start, ours has one"
                ));
            }
            continue;
        }
        let want_pieces: Vec<String> = (0..count)
            .map(|_| {
                lines
                    .next()
                    .and_then(|l| l.strip_prefix("P "))
                    .expect("piece line")
                    .to_owned()
            })
            .collect();
        cov.valid += 1;
        cov.pieces += want_pieces.len();
        for p in &want_pieces {
            if p.contains("VerticalPlacement:") {
                cov.portal_setups.insert(format!(
                    "{}|{}|{}|{}|{}",
                    tag_field(p, "VerticalPlacement:"),
                    tag_field(p, "mossiness:").trim_end_matches('f'),
                    tag_field(p, "overgrown:") == "1b",
                    tag_field(p, "vines:") == "1b",
                    tag_field(p, "replace_with_blackstone:") == "1b"
                ));
            }
            if let Some(i) = p.find("Template:\"") {
                let rest = &p[i + 10..];
                cov.templates
                    .insert(rest[..rest.find('"').unwrap()].to_owned());
            }
        }
        let Some(mut start) = start else {
            failures.push(format!(
                "start {seed} {cx} {cz}: vanilla has a start of {count} pieces, ours none"
            ));
            while lines.peek().is_some_and(|l| !l.starts_with("START")) {
                lines.next();
            }
            continue;
        };
        let context = StructurePieceSerializationContext { env: &env };
        let got_pieces: Vec<String> = start
            .piece_container
            .pieces
            .iter()
            .map(|p| Tag::Compound(p.create_tag(&context)).to_string())
            .collect();
        if got_pieces != want_pieces {
            let first = got_pieces
                .iter()
                .zip(&want_pieces)
                .position(|(a, b)| a != b)
                .unwrap_or(got_pieces.len().min(want_pieces.len()));
            failures.push(format!(
                "start {seed} {cx} {cz}: pieces differ at {first}: ours `{}`, vanilla `{}` ({} vs {} pieces)",
                got_pieces.get(first).map_or("<none>", String::as_str),
                want_pieces.get(first).map_or("<none>", String::as_str),
                got_pieces.len(),
                want_pieces.len()
            ));
            // the placements below depend on the pieces
            while lines.peek().is_some_and(|l| !l.starts_with("START")) {
                lines.next();
            }
            continue;
        }
        while lines.peek().is_some_and(|l| l.starts_with("PLACE")) {
            let place: Vec<&str> = lines.next().unwrap().split(' ').collect();
            let (px, pz, index) = (
                place[1].parse::<i32>().unwrap(),
                place[2].parse::<i32>().unwrap(),
                place[3].parse::<i32>().unwrap(),
            );
            let mut expected = Vec::new();
            for line in lines.by_ref() {
                if line == "END" {
                    break;
                }
                expected.push(line.strip_prefix("D ").expect("dump line").to_owned());
            }
            let mut synth = SynthRegion::new(seed, px, pz, ChunkStatus::Features, 1);
            let before = snapshot(&synth);
            let place_env = synth.env.clone();
            let mut level = synth.level();
            let mut random = WorldgenRandom::new(Box::new(LegacyRandomSource::new(0)));
            let decoration_seed = random.set_decoration_seed(seed, px * 16, pz * 16);
            random.set_feature_seed(
                decoration_seed,
                index,
                structure.value().step().ordinal() as i32,
            );
            let (min_x, min_z) = (px * 16, pz * 16);
            let writable = BoundingBox::new(
                min_x,
                MIN_Y + 1,
                min_z,
                min_x + 15,
                MIN_Y + HEIGHT - 1,
                min_z + 15,
            );
            let manager = StructureManager::new(&place_env);
            start.place_in_chunk(
                &mut level,
                &manager,
                &place_env,
                &mut random,
                &writable,
                ChunkPos::new(px, pz),
            );
            let dumped = dump(&mut level, &before);
            let got: Vec<String> = (if full_mode().is_some() {
                dumped
            } else {
                fold(dumped)
            })
            .into_iter()
            .map(|l| {
                if l.starts_with("N ") {
                    normalize_entity(&l, id == "igloo")
                } else {
                    l
                }
            })
            .collect();
            cov.placements += 1;
            cov.dump_lines += expected.len();
            for (n, needle) in needles.iter().enumerate() {
                cov.needles[n] += expected.iter().filter(|l| l.contains(needle)).count();
            }
            if got != expected {
                let first = got
                    .iter()
                    .zip(&expected)
                    .position(|(a, b)| a != b)
                    .unwrap_or(got.len().min(expected.len()));
                failures.push(format!(
                    "start {seed} {cx} {cz} place {px} {pz}: dump differs at line {first}: ours `{}`, vanilla `{}` ({} vs {} lines)",
                    got.get(first).map_or("<none>", String::as_str),
                    expected.get(first).map_or("<none>", String::as_str),
                    got.len(),
                    expected.len()
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{id}: {} starts, {} pieces, {} placements, {} failures:\n{}",
        cov.starts,
        cov.pieces,
        cov.placements,
        failures.len(),
        failures
            .iter()
            .take(6)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    cov
}

/// Every `.nbt` template of `dir` in the vanilla data pack (`minecraft:<dir>/<name>`).
fn pack_templates(dir: &str) -> BTreeSet<String> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../ref/src/data/minecraft/structure")
        .join(dir);
    std::fs::read_dir(&root)
        .unwrap_or_else(|e| panic!("{root:?}: {e}"))
        .filter_map(|e| {
            e.unwrap()
                .file_name()
                .into_string()
                .unwrap()
                .strip_suffix(".nbt")
                .map(|n| format!("minecraft:{dir}/{n}"))
        })
        .collect()
}

fn assert_all_templates(covered: &BTreeSet<String>, expected: &BTreeSet<String>, what: &str) {
    let missing: Vec<&String> = expected.difference(covered).collect();
    assert!(
        missing.is_empty(),
        "{what}: fixture never places {missing:?}"
    );
}

fn assert_substantial(c: &Coverage, starts: usize, valid: usize, placements: usize) {
    assert!(
        c.starts >= starts
            && c.valid >= valid
            && c.placements >= placements
            && c.dump_lines > c.placements * 5,
        "fixture too small"
    );
}

#[test]
fn desert_pyramid_matches_vanilla() {
    let c = check(
        "desert_pyramid",
        false,
        &[
            "minecraft:chest",
            "minecraft:brushable_block",
            "archaeology/desert_pyramid",
        ],
    );
    assert_substantial(&c, 120, 40, 80);
    assert!(
        c.needles.iter().all(|n| *n > 0),
        "fixture lacks chests/suspicious sand: {:?}",
        c.needles
    );
}

#[test]
fn jungle_pyramid_matches_vanilla() {
    let c = check(
        "jungle_pyramid",
        false,
        &[
            "minecraft:dispenser",
            "minecraft:chest",
            "chests/jungle_temple",
        ],
    );
    assert_substantial(&c, 120, 40, 40);
    assert!(
        c.needles.iter().all(|n| *n > 0),
        "fixture lacks dispensers/chests: {:?}",
        c.needles
    );
}

#[test]
fn swamp_hut_matches_vanilla() {
    let c = check("swamp_hut", false, &["minecraft:witch", "minecraft:cat"]);
    assert_substantial(&c, 60, 55, 55);
    assert!(
        c.needles.iter().all(|n| *n > 0),
        "fixture lacks mobs: {:?}",
        c.needles
    );
}

#[test]
fn igloo_matches_vanilla() {
    let c = check("igloo", false, &["chests/igloo_chest"]);
    assert_substantial(&c, 90, 40, 90);
    assert!(
        c.needles.iter().all(|n| *n > 0),
        "fixture lacks chests: {:?}",
        c.needles
    );
    assert_all_templates(&c.templates, &pack_templates("igloo"), "igloo");
}

#[test]
fn buried_treasure_matches_vanilla() {
    let c = check("buried_treasure", false, &["chests/buried_treasure"]);
    assert_substantial(&c, 45, 20, 20);
    assert!(
        c.needles.iter().all(|n| *n > 0),
        "fixture lacks chests: {:?}",
        c.needles
    );
}

#[test]
fn shipwreck_matches_vanilla() {
    let ocean = check(
        "shipwreck",
        false,
        &[
            "chests/shipwreck_map",
            "chests/shipwreck_treasure",
            "chests/shipwreck_supply",
        ],
    );
    assert_substantial(&ocean, 150, 100, 150);
    let beached = check(
        "shipwreck_beached",
        false,
        &[
            "chests/shipwreck_map",
            "chests/shipwreck_treasure",
            "chests/shipwreck_supply",
        ],
    );
    assert_substantial(&beached, 90, 60, 90);
    for c in [&ocean, &beached] {
        assert!(
            c.needles.iter().all(|n| *n > 0),
            "fixture lacks a loot chest kind: {:?}",
            c.needles
        );
    }
    let all: BTreeSet<String> = ocean.templates.union(&beached.templates).cloned().collect();
    assert_all_templates(&all, &pack_templates("shipwreck"), "shipwreck");
}

#[test]
fn ocean_ruin_matches_vanilla() {
    let warm = check(
        "ocean_ruin_warm",
        false,
        &[
            "chests/underwater_ruin_small",
            "chests/underwater_ruin_big",
            "minecraft:drowned",
        ],
    );
    assert_substantial(&warm, 150, 100, 150);
    let cold = check(
        "ocean_ruin_cold",
        false,
        &[
            "chests/underwater_ruin_small",
            "chests/underwater_ruin_big",
            "minecraft:drowned",
        ],
    );
    assert_substantial(&cold, 150, 100, 150);
    for c in [&warm, &cold] {
        assert!(
            c.needles.iter().all(|n| *n > 0),
            "fixture lacks a chest kind / drowned: {:?}",
            c.needles
        );
    }
    let all: BTreeSet<String> = warm.templates.union(&cold.templates).cloned().collect();
    assert_all_templates(&all, &pack_templates("underwater_ruin"), "ocean ruin");
}

#[test]
fn ruined_portal_matches_vanilla() {
    let mut templates = BTreeSet::new();
    let mut setups = BTreeSet::new();
    let mut declared = BTreeSet::new();
    let mut lava = 0;
    for (id, nether) in [
        ("ruined_portal", false),
        ("ruined_portal_desert", false),
        ("ruined_portal_jungle", false),
        ("ruined_portal_swamp", false),
        ("ruined_portal_mountain", false),
        ("ruined_portal_ocean", false),
        ("ruined_portal_nether", true),
    ] {
        let c = check(
            id,
            nether,
            &[
                "minecraft:lava",
                "minecraft:nether_portal",
                "minecraft:vine",
            ],
        );
        assert_substantial(&c, 45, 30, 40);
        lava += c.needles[0];
        templates.extend(c.templates);
        setups.extend(c.portal_setups);
        // every setup of the structure's json (`placement` -> `VerticalPlacement` serialized name)
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data");
        let json: serde_json::Value = serde_json::from_slice(
            &std::fs::read(root.join(format!("minecraft/worldgen/structure/{id}.json"))).unwrap(),
        )
        .unwrap();
        for setup in json["setups"].as_array().unwrap() {
            let float = |key: &str| format!("{:?}", setup[key].as_f64().unwrap() as f32);
            declared.insert(format!(
                "{}|{}|{}|{}|{}",
                setup["placement"].as_str().unwrap(),
                float("mossiness"),
                setup["overgrown"].as_bool().unwrap(),
                setup["vines"].as_bool().unwrap(),
                setup["replace_with_blackstone"].as_bool().unwrap()
            ));
        }
    }
    assert!(lava > 0, "no lava placed");
    assert_all_templates(&setups, &declared, "ruined portal setup");
    assert_all_templates(
        &templates,
        &pack_templates("ruined_portal"),
        "ruined portal",
    );
}

#[test]
fn nether_fossil_matches_vanilla() {
    let c = check("nether_fossil", true, &[]);
    assert_substantial(&c, 300, 100, 100);
    assert_all_templates(
        &c.templates,
        &pack_templates("nether_fossils"),
        "nether fossil",
    );
}
